{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.INVENTORY_RECONCILIATION_SUMMARY_V2 AS WITH excluded_skus AS ( SELECT DISTINCT UPPER(TRIM(\"Item SkuCode\")) AS sku FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY WHERE NULLIF( TRIM(\"Item SkuCode\"), \'\' ) IS NOT NULL AND ( UPPER(TRIM(COALESCE(\"Category Name\", \'\'))) IN ( \'NON- TRADING\', \'NON-TRADING\', \'CARRY BAG\' ) OR UPPER(TRIM(COALESCE(BRAND, \'\'))) = \'GENERAL\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'NT%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'CBB%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'TEST%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'%HANGER%\' OR REGEXP_LIKE( UPPER(TRIM(\"Item SkuCode\")), \'^[0-9]+$\' ) ) ), uc_stock AS ( SELECT CASE WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH1\' THEN 2 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH2\' THEN 8 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-NORTH-TAURU\' THEN 94 END AS branch_code, UPPER(TRIM(u.\"Item SkuCode\")) AS sku, SUM( COALESCE(u.INVENTORY, 0) + COALESCE(u.\"Inventory Blocked\", 0) + COALESCE(u.\"Bad Inventory\", 0) + COALESCE(u.\"Inventory Not Synced\", 0) ) AS uc_stock FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY u WHERE UPPER(TRIM(u.FACILITY)) IN ( \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\' ) AND NULLIF( TRIM(u.\"Item SkuCode\"), \'\' ) IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(u.\"Item SkuCode\")) ) GROUP BY CASE WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH1\' THEN 2 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-WH2\' THEN 8 WHEN UPPER(TRIM(u.FACILITY)) = \'SAPL-NORTH-TAURU\' THEN 94 END, UPPER(TRIM(u.\"Item SkuCode\")) ), logic_latest_date AS ( SELECT BRANCH_CODE, MAX(DATE) AS stock_date FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND WHERE BRANCH_CODE IN ( 2, 8, 94 ) GROUP BY BRANCH_CODE ), logic_stock AS ( SELECT l.DATE AS stock_date, l.BRANCH_CODE AS branch_code, UPPER(TRIM(l.ADDLITEMCODE)) AS sku, SUM( CASE WHEN UPPER(TRIM(l.GODOWN_NAME)) IN ( \'GOOD_INVENTORY\', \'BAD_INVENTORY\' ) THEN COALESCE(l.STOCK_QTY, 0) ELSE 0 END ) AS logic_stock FROM SNITCH_DB.MAPLEMONK.LOGICERP_WAREHOUSE_GET_STOCK_IN_HAND l JOIN logic_latest_date d ON l.BRANCH_CODE = d.BRANCH_CODE AND l.DATE = d.stock_date WHERE l.BRANCH_CODE IN ( 2, 8, 94 ) AND UPPER(TRIM(l.GODOWN_NAME)) IN ( \'GOOD_INVENTORY\', \'BAD_INVENTORY\' ) AND NULLIF( TRIM(l.ADDLITEMCODE), \'\' ) IS NOT NULL AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'NT%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'CBB%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'TEST%\' AND UPPER(TRIM(l.ADDLITEMCODE)) NOT LIKE \'%HANGER%\' AND NOT REGEXP_LIKE( UPPER(TRIM(l.ADDLITEMCODE)), \'^[0-9]+$\' ) AND NOT EXISTS ( SELECT 1 FROM excluded_skus x WHERE x.sku = UPPER(TRIM(l.ADDLITEMCODE)) ) GROUP BY l.DATE, l.BRANCH_CODE, UPPER(TRIM(l.ADDLITEMCODE)) ), reco AS ( SELECT COALESCE( uc.branch_code, logic.branch_code ) AS branch_code, logic.stock_date, COALESCE( uc.sku, logic.sku ) AS sku, COALESCE( uc.uc_stock, 0 ) AS uc_stock, COALESCE( logic.logic_stock, 0 ) AS logic_stock FROM uc_stock uc FULL OUTER JOIN logic_stock logic ON uc.branch_code = logic.branch_code AND uc.sku = logic.sku ), filtered AS ( SELECT branch_code, stock_date, sku, uc_stock, logic_stock, uc_stock - logic_stock AS stock_difference, ABS( uc_stock - logic_stock ) AS absolute_stock_difference FROM reco WHERE GREATEST( ABS(uc_stock), ABS(logic_stock) ) > 0 ), summary AS ( SELECT branch_code, MAX(stock_date) AS stock_date, CASE WHEN branch_code = 2 THEN \'SAPL-WH1\' WHEN branch_code = 8 THEN \'SAPL-WH2\' WHEN branch_code = 94 THEN \'SAPL-NORTH-TAURU\' END AS facility, CASE WHEN branch_code = 2 THEN \'SNITCH - WH - YELHANKA\' WHEN branch_code = 8 THEN \'SNITCH - WH - YELHANKA 2\' WHEN branch_code = 94 THEN \'SNITCH - WH - NORTH\' END AS logic_warehouse, COUNT(*) AS stocked_skus, COUNT_IF( uc_stock = logic_stock ) AS exact_matched_skus, COUNT_IF( ABS( uc_stock - logic_stock ) <= 1 ) AS matched_within_1_skus, COUNT_IF( ABS( uc_stock - logic_stock ) <= 5 ) AS matched_within_5_skus, COUNT_IF( uc_stock <> logic_stock ) AS mismatched_skus, COUNT_IF( uc_stock = 0 AND logic_stock <> 0 ) AS missing_in_uc_skus, COUNT_IF( logic_stock = 0 AND uc_stock <> 0 ) AS missing_in_logic_skus, SUM(uc_stock) AS uc_stock, SUM(logic_stock) AS logic_stock, SUM( stock_difference ) AS net_stock_difference, SUM( absolute_stock_difference ) AS absolute_stock_difference, SUM( LEAST( GREATEST(uc_stock, 0), GREATEST(logic_stock, 0) ) ) AS matched_stock_units, ROUND( COUNT_IF( uc_stock = logic_stock ) * 100.0 / NULLIF( COUNT(*), 0 ), 2 ) AS exact_sku_match_pct, ROUND( COUNT_IF( ABS( uc_stock - logic_stock ) <= 1 ) * 100.0 / NULLIF( COUNT(*), 0 ), 2 ) AS within_1_match_pct, ROUND( COUNT_IF( ABS( uc_stock - logic_stock ) <= 5 ) * 100.0 / NULLIF( COUNT(*), 0 ), 2 ) AS within_5_match_pct, ROUND( SUM( LEAST( GREATEST(uc_stock, 0), GREATEST(logic_stock, 0) ) ) * 100.0 / NULLIF( GREATEST( SUM( GREATEST( uc_stock, 0 ) ), SUM( GREATEST( logic_stock, 0 ) ) ), 0 ), 2 ) AS stock_unit_match_pct FROM filtered GROUP BY branch_code ), final_output AS ( SELECT stock_date, TO_VARCHAR(branch_code) AS branch_code, facility, logic_warehouse, stocked_skus, exact_matched_skus, matched_within_1_skus, matched_within_5_skus, mismatched_skus, missing_in_uc_skus, missing_in_logic_skus, uc_stock, logic_stock, net_stock_difference, absolute_stock_difference, matched_stock_units, exact_sku_match_pct, within_1_match_pct, within_5_match_pct, stock_unit_match_pct FROM summary UNION ALL SELECT MAX(stock_date) AS stock_date, \'TOTAL\' AS branch_code, \'ALL WAREHOUSES\' AS facility, \'ALL WAREHOUSES\' AS logic_warehouse, SUM(stocked_skus), SUM(exact_matched_skus), SUM(matched_within_1_skus), SUM(matched_within_5_skus), SUM(mismatched_skus), SUM(missing_in_uc_skus), SUM(missing_in_logic_skus), SUM(uc_stock), SUM(logic_stock), SUM(net_stock_difference), SUM(absolute_stock_difference), SUM(matched_stock_units), ROUND( SUM(exact_matched_skus) * 100.0 / NULLIF( SUM(stocked_skus), 0 ), 2 ), ROUND( SUM(matched_within_1_skus) * 100.0 / NULLIF( SUM(stocked_skus), 0 ), 2 ), ROUND( SUM(matched_within_5_skus) * 100.0 / NULLIF( SUM(stocked_skus), 0 ), 2 ), ROUND( SUM(matched_stock_units) * 100.0 / NULLIF( GREATEST( SUM( GREATEST( uc_stock, 0 ) ), SUM( GREATEST( logic_stock, 0 ) ) ), 0 ), 2 ) FROM summary ) SELECT stock_date, branch_code, facility, logic_warehouse, stocked_skus, exact_matched_skus, matched_within_1_skus, matched_within_5_skus, mismatched_skus, missing_in_uc_skus, missing_in_logic_skus, uc_stock, logic_stock, net_stock_difference, absolute_stock_difference, matched_stock_units, exact_sku_match_pct, within_1_match_pct, within_5_match_pct, stock_unit_match_pct FROM final_output ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            